import assert from "node:assert/strict";
import { distribution } from "./w01-capture";
import { proofErrors } from "./p07-proof-errors";
export type CurrentExpected={projectId:string;workflowId:string;revisionId:string;nodeId:string;scenario:number;index:number;context:number;view:"graph"|"list";origin:string;taskId:string;version:number;workRevision:number;reworkRound:number;artifactRef:string;ready:boolean;decision:string;eventId:string};
export type CurrentCapture=CurrentExpected & {elapsedMs:number;frames:number;matched:number;exact:boolean;visible:boolean;hitTest:boolean;observed?:Record<string,string|undefined>[]};
export function summarizeCurrent(expected:CurrentExpected[],captures:CurrentCapture[]){
 const key=(x:CurrentExpected)=>`${x.scenario}:${x.index}:${x.context}:${x.origin}`,wanted=new Map(expected.map(e=>[key(e),e]));assert.equal(wanted.size,expected.length,"duplicate expected identities");const seen=new Map<string,number>(),present=new Set<string>(),confirmed=new Set<string>();let wrong=0,hidden=0,late=0;
 for(const c of captures){const k=key(c),e=wanted.get(k);seen.set(k,(seen.get(k)??0)+1);const bound=!!e&&Object.keys(e).every(field=>e[field as keyof CurrentExpected]===c[field as keyof CurrentExpected]);if(bound&&c.matched>0)present.add(k);if(!bound||!c.exact)wrong++;if(!c.visible||!c.hitTest)hidden++;if(!Number.isFinite(c.elapsedMs)||c.elapsedMs>=2000)late++;if(bound&&c.exact&&c.visible&&c.hitTest&&c.frames===2&&c.matched===1&&Number.isFinite(c.elapsedMs)&&c.elapsedMs>=0)confirmed.add(k);}
 const missing=expected.length-present.size,unconfirmed=expected.length-confirmed.size,duplicate=[...seen.values()].reduce((n,c)=>n+Math.max(0,c-1),0)+captures.reduce((n,c)=>n+Math.max(0,c.matched-1),0);
 return {expected:expected.length,captured:captures.length,missing,unconfirmed,duplicate,wrong,hidden,late,valid:!missing&&!unconfirmed&&!duplicate&&!wrong&&!hidden&&!late,distribution:captures.length&&captures.every(c=>Number.isFinite(c.elapsedMs)&&c.elapsedMs>=0)?distribution(captures.map(c=>c.elapsedMs)):null};
}
export function summarizeSamples(expected:{id:string;warmup:boolean}[],samples:{id:string;warmup:boolean;elapsedMs:number;status:number}[]){
 assert.equal(new Set(expected.map(e=>e.id)).size,expected.length);assert.equal(samples.length,expected.length,"all original warm and measured samples required");assert.equal(new Set(samples.map(e=>e.id)).size,samples.length);for(const e of expected){const s=samples.find(s=>s.id===e.id);assert(s&&s.warmup===e.warmup&&s.status>=200&&s.status<300&&Number.isFinite(s.elapsedMs)&&s.elapsedMs>=0,"missing/failed/nonfinite sample");}return distribution(samples.filter(s=>!s.warmup).map(s=>s.elapsedMs));
}
export async function teardownAll(primary:unknown,resources:{name:string;close:()=>Promise<void>}[],failures:unknown[]){const errors=proofErrors(()=>{});if(primary!==undefined)errors.capture("primary",primary);for(const resource of resources)await errors.attempt(resource.name,resource.close);failures.push(...errors.facts.errors);errors.throwFirst();}
// Browser clock only bounds this wait. Controller measures dispatch through return.
export async function currentFrames(e:CurrentExpected & {captureBoundMs?:number}){let frames=0,result={frames:0,matched:0,exact:false,visible:false,hitTest:false,observed:[] as Record<string,string|undefined>[]};const start=performance.now();while(performance.now()-start<(e.captureBoundMs??5000)){await new Promise<void>(resolve=>requestAnimationFrame(()=>resolve()));const panels=[...document.querySelectorAll<HTMLElement>(`.acceptance-facts[data-task-id="${CSS.escape(e.taskId)}"]`)];const p=panels[0],heading=p?.querySelector<HTMLElement>(".task-section-heading"),box=heading?.getBoundingClientRect();const url=new URL(location.href);const route=location.pathname===`/projects/${e.projectId}/workflows`&&url.searchParams.get("workflowId")===e.workflowId&&url.searchParams.get("revisionId")===e.revisionId&&url.searchParams.get("nodeId")===e.nodeId&&(url.searchParams.get("view")==="list"?"list":"graph")===e.view;const exact=route&&panels.length===1&&!!p&&p.dataset.workRevision===String(e.workRevision)&&p.dataset.reworkRound===String(e.reworkRound)&&p.dataset.artifactRef===e.artifactRef&&p.dataset.ready===String(e.ready)&&p.dataset.taskVersion===String(e.version)&&p.dataset.reviewDecision===e.decision&&p.dataset.reviewEventId===e.eventId;
 const visible=!!heading&&!!box&&heading.checkVisibility({checkOpacity:true,checkVisibilityCSS:true})&&box.top>=0&&box.bottom<=innerHeight&&box.left>=0&&box.right<=innerWidth;const hitTest=visible&&!!heading&&!!box&&heading.contains(document.elementFromPoint(box.x+box.width/2,box.y+box.height/2));frames=exact&&visible&&hitTest?frames+1:0;result={frames,matched:panels.length,exact,visible,hitTest,observed:panels.map(p=>({...p.dataset,route:location.href}))};if(frames===2)return result;}return result;}
